  --input: hsl(217.2, 32.6%, 17.5%);
  --ring: hsl(212.7, 26.8%, 83.9%);
}

@layer base {
  * {
    @apply border-border;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-background text-foreground;
    font-family: 'Inter', 'Arial', sans-serif;
  }
}

@layer components {
  .gradient-primary {
    background: linear-gradient(135deg, var(--pool-gradient-start) 0%, var(--pool-gradient-end) 100%);
  }

  .gradient-soft {
    background: linear-gradient(135deg, var(--pool-soft-bg) 0%, var(--pool-soft-orange) 100%);
  }

  .text-gradient {
    background: linear-gradient(135deg, var(--pool-gradient-start) 0%, var(--pool-gradient-end) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    color: transparent;
  }

  /* Enhanced glass-morphism for sunset background */
  .glass-card {
    background: rgba(255, 255, 255, 0.15);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 16px;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.4), 0 0 60px rgba(255, 165, 0, 0.1);
  }

  /* Magical sunset infinity edge pool and spa background */
  .hero-3d-background {
    background-image: url('/attached_assets/image 18_1758486893797.png');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  /* Magical text shadows for sunset background */
  .hero-heading {
    text-shadow: 2px 2px 8px rgba(0,0,0,0.9), 0 0 30px rgba(255,140,0,0.3), 0 0 60px rgba(255,69,0,0.2);
  }

  .hero-description {
    text-shadow: 1px 1px 4px rgba(0,0,0,0.9), 0 0 20px rgba(0,0,0,0.5);
  }
}

@layer utilities {
  @keyframes float {
    0%, 100% { 
      transform: translateY(0px); 
    }
    50% { 
      transform: translateY(-10px); 
    }
  }

  .float-animation {
    animation: float 3s ease-in-out infinite;
  }

  @keyframes fadeInUp {
    from {
      opacity: 0;
      transform: translateY(30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .fade-in {
    animation: fadeInUp 0.8s ease-out;
  }
}

