              />
              <FormField
                control={form.control}
                name="poolWidth"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Pool Width (feet) *</FormLabel>
                    <FormControl>
                      <Input type="number" {...field} data-testid="input-pool-width" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="shallowDepth"
                render={({ field }) => (
                  <FormItem>
